===== cache/addr_define.vh =====
     1	localparam 
     2	// | ----------- address 32 ----------- |
     3	// | tag 23 | index 5 | word 2 | byte 2 |
     4	    ADDR_BITS = 32,
     5	    WORD_BYTES = 4,
     6	    WORD_BYTES_WIDTH = 2,   // log2(4 (WORD_BYTES))
     7	    WORD_BITS = (WORD_BYTES * 8),
     8	    ELEMENT_WORDS = 4,
     9	    ELEMENT_WORDS_WIDTH = 2,   // log2(4 (ELEMENT_WORDS))
    10	    BLOCK_WIDTH = (ELEMENT_WORDS_WIDTH + WORD_BYTES_WIDTH),   // 4
    11	    ELEMENT_NUM = 64,
    12	    WAYS = 2,
    13	    ELEMENT_INDEX_WIDTH = 6,   // log2(64)
    14	    SET_INDEX_WIDTH = 5,   // log2(64 / 2 (WAYS))
    15	    TAG_BITS = (ADDR_BITS - SET_INDEX_WIDTH - BLOCK_WIDTH);  // 32 - 5 - 4 = 23
    16	    ===== cache/cache.v =====
     1	// | ----------- address 32 ----------- |
     2	// | 31   9 | 8     4 | 3    2 | 1    0 |
     3	// | tag 23 | index 5 | word 2 | byte 2 |
     4	
     5	module cache (
     6		input wire clk,  // clock
     7		input wire rst,  // reset
     8		input wire [ADDR_BITS-1:0] addr,  // address
     9	    input wire load,    //  read refreshes recent bit
    10		input wire store,  // set valid to 1 and reset dirty to 0
    11		input wire edit,  // set dirty to 1
    12		input wire invalid,  // reset valid to 0
    13	    input wire [2:0] u_b_h_w, // select signed or not & data width
    14	                              // please refer to definition of LB, LH, LW, LBU, LHU in RV32I Instruction Set  
    15		input wire [31:0] din,  // data write in
    16		output reg hit = 0,  // hit or not
    17		output reg [31:0] dout = 0,  // data read out
    18		output reg valid = 0,  // valid bit
    19		output reg dirty = 0,  // dirty bit
    20		output reg [TAG_BITS-1:0] tag = 0  // tag bits
    21		);
    22	
    23	    `include "addr_define.vh"
    24	
    25	    wire [31:0] word1, word2;
    26	    wire [15:0] half_word1, half_word2;
    27	    wire [7:0]  byte1, byte2;
    28	    wire recent1, recent2, valid1, valid2, dirty1, dirty2;
    29	    wire [TAG_BITS-1:0] tag1, tag2;
    30	    wire hit1, hit2;
    31	
    32	    reg [ELEMENT_NUM-1:0] inner_recent = 0; // for LRU
    33	    reg [ELEMENT_NUM-1:0] inner_valid = 0;
    34	    reg [ELEMENT_NUM-1:0] inner_dirty = 0;
    35	    reg [TAG_BITS-1:0] inner_tag [0:ELEMENT_NUM-1];
    36	    // 64 elements, 2 ways set associative => 32 sets
    37	    reg [31:0] inner_data [0:ELEMENT_NUM*ELEMENT_WORDS-1];
    38	
    39	    // initialize tag and data with 0
    40	    integer i;
    41	    initial begin
    42	        for (i = 0; i < ELEMENT_NUM; i = i + 1)
    43	            inner_tag[i] = 23'b0;
    44	
    45	        for (i = 0; i < ELEMENT_NUM*ELEMENT_WORDS; i = i + 1)
    46	            inner_data[i] = 32'b0;
    47	    end
    48	
    49	    // the bits in an input address:
    50	    wire [TAG_BITS-1:0] addr_tag;
    51	    wire [SET_INDEX_WIDTH-1:0] addr_index;     // idx of set
    52	    wire [ELEMENT_INDEX_WIDTH-1:0] addr_element1; 
    53	    wire [ELEMENT_INDEX_WIDTH-1:0] addr_element2;     // idx of element
    54	    wire [ELEMENT_INDEX_WIDTH+ELEMENT_WORDS_WIDTH-1:0] addr_word1;
    55	    wire [ELEMENT_INDEX_WIDTH+ELEMENT_WORDS_WIDTH-1:0] addr_word2; // element index + word index
    56	
    57	    assign addr_tag = ;             //need to fill in
    58	    assign addr_index = ;           //need to fill in
    59	    assign addr_element1 = {addr_index, 1'b0};
    60	    assign addr_element2 = ;      //need to fill in
    61	    assign addr_word1 = {addr_element1, addr[ELEMENT_WORDS_WIDTH+WORD_BYTES_WIDTH-1:WORD_BYTES_WIDTH]};
    62	    assign addr_word2 = ;           //need to fill in
    63	
    64	    assign word1 = inner_data[addr_word1];
    65	    assign word2 = ;                //need to fill in
    66	    assign half_word1 = addr[1] ? word1[31:16] : word1[15:0];
    67	    assign half_word2 = ;           //need to fill in
    68	    assign byte1 = addr[1] ?
    69	                    addr[0] ? word1[31:24] : word1[23:16] :
    70	                    addr[0] ? word1[15:8] :  word1[7:0]   ;
    71	    assign byte2 = ;                //need to fill in
    72	
    73	    assign recent1 = inner_recent[addr_element1];
    74	    assign recent2 = ;              //need to fill in
    75	    assign valid1 = inner_valid[addr_element1];
    76	    assign valid2 = ;               //need to fill in
    77	    assign dirty1 = inner_dirty[addr_element1];
    78	    assign dirty2 = ;               //need to fill in
    79	    assign tag1 = inner_tag[addr_element1];
    80	    assign tag2 = ;                 //need to fill in
    81	
    82	    assign hit1 = valid1 & (tag1 == addr_tag);
    83	    assign hit2 = ;                 //need to fill in
    84	
    85	    always @ (posedge clk) begin
    86	        valid <= ;                  //need to fill in
    87	        dirty <= ;                  //need to fill in
    88	        tag <= ;                    //need to fill in
    89	        hit <= ;                    //need to fill in
    90	        
    91	        // read $ with load==0 means moving data from $ to mem
    92	        // no need to update recent bit
    93	        // otherwise the refresh process will be affected
    94	        if (load) begin
    95	            if (hit1) begin
    96	                dout <=
    97	                    u_b_h_w[1] ? word1 :
    98	                    u_b_h_w[0] ? {u_b_h_w[2] ? 16'b0 : {16{half_word1[15]}}, half_word1} :
    99	                    {u_b_h_w[2] ? 24'b0 : {24{byte1[7]}}, byte1};
   100	                
   101	                // inner_recent will be refreshed only on r/w hit
   102	                // (including the r/w hit after miss and replacement)
   103	                inner_recent[addr_element1] <= 1'b1;
   104	                inner_recent[addr_element2] <= 1'b0;
   105	            end
   106	            else if (hit2) begin
   107	                    //need to fill in
   108	            end
   109	        end
   110	        else dout <= inner_data[ recent1 ? addr_word2 : addr_word1 ];
   111	
   112	        if (edit) begin
   113	            if (hit1) begin
   114	                inner_data[addr_word1] <= 
   115	                    u_b_h_w[1] ?        // word?
   116	                        din
   117	                    :
   118	                        u_b_h_w[0] ?    // half word?
   119	                            addr[1] ?       // upper / lower?
   120	                                {din[15:0], word1[15:0]} 
   121	                            :
   122	                                {word1[31:16], din[15:0]} 
   123	                        :   // byte
   124	                            addr[1] ?
   125	                                addr[0] ?
   126	                                    {din[7:0], word1[23:0]}   // 11
   127	                                :
   128	                                    {word1[31:24], din[7:0], word1[15:0]} // 10
   129	                            :
   130	                                addr[0] ?
   131	                                    {word1[31:16], din[7:0], word1[7:0]}   // 01
   132	                                :
   133	                                    {word1[31:8], din[7:0]} // 00
   134	                ;
   135	                inner_dirty[addr_element1] <= 1'b1;
   136	                inner_recent[addr_element1] <= 1'b1;
   137	                inner_recent[addr_element2] <= 1'b0;
   138	            end
   139	            else if (hit2) begin
   140	                    //need to fill in
   141	            end
   142	        end
   143	
   144	        if (store) begin
   145	            if (recent1) begin  // replace 2
   146	                inner_data[addr_word2] <= din;
   147	                inner_valid[addr_element2] <= 1'b1;
   148	                inner_dirty[addr_element2] <= 1'b0;
   149	                inner_tag[addr_element2] <= addr_tag;
   150	            end else begin
   151	                // recent2 == 1 => replace 1
   152	                // recent2 == 0 => no data in this set, place to 1
   153	                //need to fill in
   154	            end
   155	        end
   156	
   157	        // not used currently, can be used to reset the cache.
   158	        if (invalid) begin
   159	            inner_recent[addr_element1] <= 1'b0;
   160	            inner_recent[addr_element2] <= 1'b0;
   161	            inner_valid[addr_element1] <= 1'b0;
   162	            inner_valid[addr_element2] <= 1'b0;
   163	            inner_dirty[addr_element1] <= 1'b0;
   164	            inner_dirty[addr_element2] <= 1'b0;
   165	        end
   166	    end
   167	
   168	endmodule
===== cache/cmu.v =====
     1	module cmu (
     2	        // CPU side
     3			input clk,
     4			input rst,
     5			input [31:0] addr_rw,
     6			input en_r,
     7			input en_w,
     8	        input [2:0] u_b_h_w,
     9			input [31:0] data_w,
    10			output [31:0] data_r,
    11			output stall,
    12	
    13	        // mem side
    14			output reg mem_cs_o = 0,
    15			output reg mem_we_o = 0,
    16			output reg [31:0] mem_addr_o = 0,
    17			input [31:0] mem_data_i,
    18			output [31:0] mem_data_o,
    19			input mem_ack_i,
    20	
    21	        // debug info
    22	        output [2:0] cmu_state
    23		);
    24	
    25	    `include "addr_define.vh"
    26	
    27	    reg [ADDR_BITS-1:0] cache_addr = 0;
    28	    reg cache_load = 0;
    29	    reg cache_store = 0;
    30	    reg cache_edit = 0;
    31	    reg [2:0] cache_u_b_h_w = 0;
    32	    reg [WORD_BITS-1:0] cache_din = 0;
    33	    wire cache_hit;
    34	    wire [WORD_BITS-1:0] cache_dout;
    35	    wire cache_valid;
    36	    wire cache_dirty;
    37	    wire [TAG_BITS-1:0] cache_tag;
    38	
    39	    cache CACHE (
    40	        .clk(~clk),
    41	        .rst(rst),
    42	        .addr(cache_addr),
    43	        .load(cache_load),
    44	        .store(cache_store),
    45	        .edit(cache_edit),
    46	        .invalid(1'b0),
    47	        .u_b_h_w(cache_u_b_h_w),
    48	        .din(cache_din),
    49	        .hit(cache_hit),
    50	        .dout(cache_dout),
    51	        .valid(cache_valid),
    52	        .dirty(cache_dirty),
    53	        .tag(cache_tag)
    54	    );
    55	
    56	    localparam
    57	        S_IDLE = 0,
    58	        S_PRE_BACK = 1,
    59	        S_BACK = 2,
    60	        S_FILL = 3,
    61	        S_WAIT = 4;
    62	
    63	    reg [2:0]state = 0;
    64	    reg [2:0]next_state = 0;
    65	    reg [ELEMENT_WORDS_WIDTH-1:0]word_count = 0;
    66	    reg [ELEMENT_WORDS_WIDTH-1:0]next_word_count = 0;
    67	    assign cmu_state = state;
    68	
    69	    always @ (posedge clk) begin
    70	        if (rst) begin
    71	            state <= S_IDLE;
    72	            word_count <= 2'b00;
    73	        end
    74	        else begin
    75	            state <= next_state;
    76	            word_count <= next_word_count;
    77	        end
    78	    end
    79	
    80	    // state ctrl
    81	    always @ (*) begin
    82	        if (rst) begin
    83	            next_state = S_IDLE;
    84	            next_word_count = 2'b00;
    85	        end
    86	        else begin
    87	            case (state)
    88	                S_IDLE: begin
    89	                    if (en_r || en_w) begin
    90	                        if (cache_hit)
    91	                            next_state = ??;
    92	                        else if (cache_valid && cache_dirty)
    93	                            next_state = ??;
    94	                        else
    95	                            next_state = ??;
    96	                    end
    97	                    next_word_count = 2'b00;
    98	                end
    99	
   100	                S_PRE_BACK: begin
   101	                    next_state = ??;
   102	                    next_word_count = 2'b00;
   103	                end
   104	
   105	                S_BACK: begin
   106	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})    // 2'b11 in default case
   107	                        next_state = ??;
   108	                    else
   109	                        next_state = ??;
   110	
   111	                    if (mem_ack_i)
   112	                        next_word_count = ??;
   113	                    else
   114	                        next_word_count = word_count;
   115	                end
   116	
   117	                S_FILL: begin
   118	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})
   119	                        next_state = ??;
   120	                    else
   121	                        next_state = ??;
   122	
   123	                    if (mem_ack_i)
   124	                        next_word_count = ??;
   125	                    else
   126	                        next_word_count = word_count;
   127	                end
   128	
   129	                S_WAIT: begin
   130	                    next_state = ??;
   131	                    next_word_count = 2'b00;
   132	                end
   133	            endcase
   134	        end
   135	    end
   136	    
   137	    // cache ctrl
   138	    always @ (*) begin
   139	        case(state)
   140	            S_IDLE, S_WAIT: begin
   141	                cache_addr = addr_rw;
   142	                cache_load = en_r;
   143	                cache_edit = en_w;
   144	                cache_store = 1'b0;
   145	                cache_u_b_h_w = u_b_h_w;
   146	                cache_din = data_w;
   147	            end
   148	            S_BACK, S_PRE_BACK: begin
   149	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   150	                cache_load = 1'b0;
   151	                cache_edit = 1'b0;
   152	                cache_store = 1'b0;
   153	                cache_u_b_h_w = 3'b010;
   154	                cache_din = 32'b0;
   155	            end
   156	            S_FILL: begin
   157	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   158	                cache_load = 1'b0;
   159	                cache_edit = 1'b0;
   160	                cache_store = mem_ack_i;
   161	                cache_u_b_h_w = 3'b010;
   162	                cache_din = mem_data_i;
   163	            end
   164	        endcase
   165	    end
   166	    assign data_r = cache_dout;
   167	
   168	    // mem ctrl
   169	    always @ (*) begin
   170	        case (next_state)
   171	            S_IDLE, S_PRE_BACK, S_WAIT: begin
   172	                mem_cs_o = 1'b0;
   173	                mem_we_o = 1'b0;
   174	                mem_addr_o = 32'b0;
   175	            end
   176	
   177	            S_BACK: begin
   178	                mem_cs_o = 1'b1;
   179	                mem_we_o = 1'b1;
   180	                mem_addr_o = {cache_tag, addr_rw[ADDR_BITS-TAG_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   181	            end
   182	
   183	            S_FILL: begin
   184	                mem_cs_o = 1'b1;
   185	                mem_we_o = 1'b0;
   186	                mem_addr_o = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
   187	            end
   188	        endcase
   189	    end
   190	    assign mem_data_o = cache_dout;
   191	
   192	    assign stall = ??;
   193	
   194	endmodule
