     1	module data_ram (
     2		input wire clk,
     3		input wire rst,
     4		input wire cs,
     5		input wire we,
     6		input wire [31:0] addr,
     7		input wire [31:0] din,
     8		output wire [31:0] dout,
     9		output wire stall,
    10		output reg ack = 0,
    11		output [2:0] ram_state
    12		);
    13		
    14		parameter
    15			ADDR_WIDTH = 11;
    16	
    17		localparam
    18			S_IDLE = 0,
    19			S_READING1 = 1,
    20			S_READING2 = 2,
    21			S_READ = 3,
    22			S_WRITING1 = 4,
    23			S_WRITING2 = 5,
    24			S_WRITE = 6;
    25		
    26		reg [31:0] data [0:(1<<ADDR_WIDTH)-1];
    27		
    28		integer i = 0;
    29		initial	begin
    30			for (i = 12; i < (1<<ADDR_WIDTH); i = i + 1) begin
    31				data[i] <= 32'b0;
    32			end
    33			$readmemh("ram.mem", data);
    34		end
    35	
    36		reg [2:0]state = 0;
    37		reg [31:0] out = 0;
    38		assign ram_state = state;
    39	
    40		reg [2:0]next_state = 0;
    41	
    42		always @ (posedge clk) begin
    43			if (rst) begin
    44				state = 0;
    45			end
    46			else begin
    47				state <= next_state;
    48			end
    49		end
    50	
    51		always @ (*) begin
    52			if (cs) begin
    53				if (we) begin
    54					if(state == S_IDLE)
    55						next_state = S_WRITING1;
    56					else if (S_WRITING1 <= state && state <= S_WRITING2)
    57						next_state = state + 1;
    58					else if (state == S_WRITE)
    59						next_state = S_IDLE;
    60					else
    61						next_state = 3'bxxx;
    62				end
    63				else begin
    64					if (S_IDLE <= state && state <= S_READING2)
    65						next_state = state + 1;
    66					else if (state == S_READ)
    67						next_state = S_IDLE;
    68					else
    69						next_state = 3'bxxx;
    70				end
    71			end
    72			else begin
    73				next_state = S_IDLE;
    74			end
    75		end
    76	
    77		always @ (posedge clk) begin
    78			if (state != S_READ && state != S_WRITE) begin
    79				ack <= 0;
    80				out <= 0;
    81			end
    82	
    83			else if (state == S_READ) begin
    84				ack <= 1;
    85				out <= data[addr[ADDR_WIDTH+1:2]];
    86			end
    87	
    88			else if (state == S_WRITE) begin
    89				ack <= 1;
    90				data[addr[ADDR_WIDTH+1:2]] <= din;
    91			end
    92	
    93			else begin
    94				ack <= 0;
    95				out <= 0;
    96			end
    97		end
    98	
    99	
   100		// always @ (posedge clk or posedge rst) begin
   101		// 	if (rst) begin
