   112		// 				end
   113		// 				else if (S_WRITING1 <= state && state <= S_WRITING2) begin
   114		// 					state <= state + 1;
   115		// 					ack <= 0;
   116	    //                 end
   117		// 				else if (state == S_WRITE) begin
   118		// 					state <= S_IDLE;
   119		// 					ack <= 1;
   120		// 					data[addr[ADDR_WIDTH+1:2]] <= din;
   121		// 				end
   122		// 				else begin
   123		// 					state <= S_IDLE;
   124		// 					ack <= 0;
   125		// 					out <= 32'hxxxxxxxx;
   126		// 				end
   127		// 			end else begin // read
   128		// 				if (S_IDLE <= state && state <= S_READING2) begin
   129		// 					state <= state + 1;
   130		// 					ack <= 0;
   131		// 					out <= 0;
   132		// 				end
   133		// 				else if (state == S_READ) begin
   134		// 					state <= S_IDLE;
   135		// 					ack <= 1;
   136		// 					out <= data[addr[ADDR_WIDTH+1:2]];
   137		// 				end
   138		// 				else begin
   139		// 					state <= S_IDLE;
   140		// 					ack <= 0;
   141		// 					out <= 32'hxxxxxxxx;
   142		// 				end
