`timescale 1ns / 1ps


module CtrlUnit(
    input[31:0] inst,
    input cmp_res,
    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
        mem_r, rs1use, rs2use,
    output [1:0] hazard_optype,
    output [2:0] ImmSel, cmp_ctrl,
    output [3:0] ALUControl,
    output JALR, MRET,

    output csr_rw, csr_w_imm_mux,

    output[1:0] exp_vector
);

    wire[6:0] funct7 = inst[31:25];
    wire[2:0] funct3 = inst[14:12];
    wire[6:0] opcode = inst[6:0];

    wire Rop = opcode == 7'b0110011;
    wire Iop = opcode == 7'b0010011;
    wire Bop = opcode == 7'b1100011;
    wire Lop = opcode == 7'b0000011;
    wire Sop = opcode == 7'b0100011;
    wire CSRop = opcode == 7'b1110011;

    wire funct7_0  = funct7 == 7'h0;
    wire funct7_32 = funct7 == 7'h20;

    wire funct3_0 = funct3 == 3'h0;
    wire funct3_1 = funct3 == 3'h1;
    wire funct3_2 = funct3 == 3'h2;
    wire funct3_3 = funct3 == 3'h3;
    wire funct3_4 = funct3 == 3'h4;
    wire funct3_5 = funct3 == 3'h5;
    wire funct3_6 = funct3 == 3'h6;
    wire funct3_7 = funct3 == 3'h7;

    wire ADD  = Rop & funct3_0 & funct7_0;
    wire SUB  = Rop & funct3_0 & funct7_32;
    wire SLL  = Rop & funct3_1 & funct7_0;
    wire SLT  = Rop & funct3_2 & funct7_0;
    wire SLTU = Rop & funct3_3 & funct7_0;
    wire XOR  = Rop & funct3_4 & funct7_0;
    wire SRL  = Rop & funct3_5 & funct7_0;
    wire SRA  = Rop & funct3_5 & funct7_32;
    wire OR   = Rop & funct3_6 & funct7_0;
    wire AND  = Rop & funct3_7 & funct7_0;

    wire ADDI  = Iop & funct3_0;	
    wire SLTI  = Iop & funct3_2;
    wire SLTIU = Iop & funct3_3;
    wire XORI  = Iop & funct3_4;
    wire ORI   = Iop & funct3_6;
    wire ANDI  = Iop & funct3_7;
    wire SLLI  = Iop & funct3_1 & funct7_0;
    wire SRLI  = Iop & funct3_5 & funct7_0;
    wire SRAI  = Iop & funct3_5 & funct7_32;

    wire BEQ = Bop & funct3_0;
    wire BNE = Bop & funct3_1;
    wire BLT = Bop & funct3_4;
    wire BGE = Bop & funct3_5;
    wire BLTU = Bop & funct3_6;
    wire BGEU = Bop & funct3_7;

    wire LB =  Lop & funct3_0;
    wire LH =  Lop & funct3_1;
    wire LW =  Lop & funct3_2;
    wire LBU = Lop & funct3_4;
    wire LHU = Lop & funct3_5;

    wire SB = Sop & funct3_0;
    wire SH = Sop & funct3_1;
    wire SW = Sop & funct3_2;

    wire LUI   = opcode == 7'b0110111;
    wire AUIPC = opcode == 7'b0010111;

    wire JAL  =  opcode == 7'b1101111;
    assign JALR = (opcode == 7'b1100111) && funct3_0;

    wire CSRRW = CSRop & funct3_1;
    wire CSRRS = CSRop & funct3_2;
    wire CSRRC = CSRop & funct3_3;
    wire CSRRWI = CSRop & funct3_5;
    wire CSRRSI = CSRop & funct3_6;
    wire CSRRCI = CSRop & funct3_7;

    assign MRET = inst == 32'b0011000_00010_00000_000_00000_1110011;
    wire ECALL = inst == 32'b0111_0011;

    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
    wire L_valid = LW | LH | LB | LHU | LBU;
    wire S_valid = SW | SH | SB;
    wire CSR_valid = CSRRW | CSRRS | CSRRC | CSRRWI | CSRRSI | CSRRCI;


    // 实现：条件分支成立或无条件跳转时置位 Branch
    assign Branch = B_valid & cmp_res | JAL | JALR;

    localparam Imm_type_I = 3'b001;
    localparam Imm_type_B = 3'b010;
    localparam Imm_type_J = 3'b011;
    localparam Imm_type_S = 3'b100;
    localparam Imm_type_U = 3'b101;
    // 实现：根据指令类型选择立即数格式
    assign ImmSel = {3{I_valid | L_valid | JALR}} & Imm_type_I |
                    {3{B_valid}}                 & Imm_type_B |
                    {3{JAL}}                     & Imm_type_J |
                    {3{S_valid}}                 & Imm_type_S |
                    {3{LUI | AUIPC}}             & Imm_type_U ;

    localparam cmp_EQ  = 3'b001;
    localparam cmp_NE  = 3'b010;
    localparam cmp_LT  = 3'b011;
    localparam cmp_LTU = 3'b100;
    localparam cmp_GE  = 3'b101;
    localparam cmp_GEU = 3'b110;
    // 实现：根据分支子类型选择 cmp_32 的比较方式
    assign cmp_ctrl = {3{BEQ }} & cmp_EQ  |
                      {3{BNE }} & cmp_NE  |
                      {3{BLT }} & cmp_LT  |
                      {3{BLTU}} & cmp_LTU |
                      {3{BGE }} & cmp_GE  |
                      {3{BGEU}} & cmp_GEU ;

    // 实现：AUIPC/JAL/JALR 使用 PC 作为 ALU 的 A 操作数
    assign ALUSrc_A = AUIPC | JAL | JALR;

    // 实现：立即数类指令使用立即数作为 ALU 的 B 操作数
    assign ALUSrc_B = I_valid | L_valid | S_valid | LUI | AUIPC;

    localparam ALU_ADD  = 4'b0001;
    localparam ALU_SUB  = 4'b0010;
    localparam ALU_AND  = 4'b0011;
    localparam ALU_OR   = 4'b0100;
    localparam ALU_XOR  = 4'b0101;
    localparam ALU_SLL  = 4'b0110;
    localparam ALU_SRL  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;
    localparam ALU_SRA  = 4'b1010;
    localparam ALU_Ap4  = 4'b1011;
    localparam ALU_Bout = 4'b1100;
    // 实现：根据指令类型产生 ALUControl
    assign ALUControl = {4{ADD  | ADDI  | L_valid | S_valid | AUIPC}} & ALU_ADD  |
                        {4{SUB }}                                     & ALU_SUB  |
                        {4{AND  | ANDI }}                             & ALU_AND  |
                        {4{OR   | ORI  }}                             & ALU_OR   |
                        {4{XOR  | XORI }}                             & ALU_XOR  |
                        {4{SLL  | SLLI }}                             & ALU_SLL  |
                        {4{SRL  | SRLI }}                             & ALU_SRL  |
                        {4{SLT  | SLTI }}                             & ALU_SLT  |
                        {4{SLTU | SLTIU}}                             & ALU_SLTU |
                        {4{SRA  | SRAI }}                             & ALU_SRA  |
                        {4{JAL  | JALR }}                             & ALU_Ap4  |
                        {4{LUI }}                                     & ALU_Bout ;

    // 实现：DatatoReg, RegWrite, mem_w, mem_r, rs1use, rs2use
    assign DatatoReg = L_valid | CSR_valid;
    assign RegWrite  = R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR | CSR_valid;
    assign mem_w     = S_valid;
    assign mem_r     = L_valid;
    assign rs1use    = R_valid | I_valid | L_valid | S_valid | B_valid | JALR |
                       CSRRW | CSRRS | CSRRC;
    assign rs2use    = R_valid | S_valid | B_valid;

    localparam hazard_optype_ALU = 2'd1;
    localparam hazard_optype_LOAD = 2'd2;
    localparam hazard_optype_STORE = 2'd3;
    // 实现：hazard_optype —— load 为 2，其它写寄存器指令为 1，store 为 3，其余为 0
    assign hazard_optype = {2{L_valid}} & hazard_optype_LOAD  |
                           {2{S_valid}} & hazard_optype_STORE |
                           {2{R_valid | I_valid | LUI | AUIPC | JAL | JALR | CSR_valid}} & hazard_optype_ALU ;

    // 实现：CSR 控制信号
    assign csr_rw        = CSR_valid;
    assign csr_w_imm_mux = CSRRWI | CSRRSI | CSRRCI;

    // 实现：异常向量 {非法指令, ecall}
    wire inst_valid = R_valid | I_valid | B_valid | L_valid | S_valid |
                      LUI | AUIPC | JAL | JALR | CSR_valid | ECALL | MRET;
    assign exp_vector = {~inst_valid, ECALL};

endmodule===== HazardDetectionUnit.v =====
`timescale 1ps/1ps

module HazardDetectionUnit(
    input clk,
    input Branch_ID, rs1use_ID, rs2use_ID,
    input[1:0] hazard_optype_ID,
    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
    output PC_EN_IF, reg_FD_stall, reg_FD_flush, reg_DE_flush,
    output forward_ctrl_ls,
    output[1:0] forward_ctrl_A, forward_ctrl_B
);

    reg[1:0] hazard_optype_EXE, hazard_optype_MEM;
    // 实现：把 ID 级的 hazard_optype 沿流水线打拍，跟踪 EXE / MEM 级指令的类型

    localparam hazard_optype_ALU = 2'd1;
    localparam hazard_optype_LOAD = 2'd2;
    localparam hazard_optype_STORE = 2'd3;

    // 实现：冒险检测与前递控制
    // Detect forwarding conditions for rs1 and rs2 against EXE and MEM stages.
    // Generate stall when load-use hazard is detected.
    // Generate forwarding selectors for ALU-to-ID and MEM-to-ID forwarding.
    // Generate load-store forwarding when store in EXE reads data produced by load in MEM.

    initial begin
        hazard_optype_EXE = 2'd0;
        hazard_optype_MEM = 2'd0;
    end

    // ID 级的读寄存器需求
    wire rs1_valid = rs1use_ID & (rs1_ID != 5'd0);
    wire rs2_valid = rs2use_ID & (rs2_ID != 5'd0);

    // EXE / MEM 级指令是否会写回寄存器
    wire EXE_write = (hazard_optype_EXE == hazard_optype_ALU) |
                     (hazard_optype_EXE == hazard_optype_LOAD);
    wire MEM_write = (hazard_optype_MEM == hazard_optype_ALU) |
                     (hazard_optype_MEM == hazard_optype_LOAD);

    wire EXE_is_load = hazard_optype_EXE == hazard_optype_LOAD;
    wire MEM_is_load = hazard_optype_MEM == hazard_optype_LOAD;

    // 相关判断
    wire rs1_EXE_conflict = rs1_valid & EXE_write & (rs1_ID == rd_EXE);
    wire rs2_EXE_conflict = rs2_valid & EXE_write & (rs2_ID == rd_EXE);
    wire rs1_MEM_conflict = rs1_valid & MEM_write & (rs1_ID == rd_MEM);
    wire rs2_MEM_conflict = rs2_valid & MEM_write & (rs2_ID == rd_MEM);

    // load-use 冒险：EXE 级是 load，ID 级需要它的结果 -> 必须暂停一拍。
    // 例外：ID 级是 store 且只有 rs2（写入的数据）相关时，可以等到 EXE/MEM 级
    //       再用 load-store 前递解决，不需要暂停。
    wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;
    wire load_use_hazard = EXE_is_load &
                           (rs1_EXE_conflict | (rs2_EXE_conflict & ~ID_is_store));

    assign reg_FD_stall = load_use_hazard;
    assign PC_EN_IF     = ~load_use_hazard;
    assign reg_DE_flush = load_use_hazard;            // 向 EXE 级插入气泡
    assign reg_FD_flush = Branch_ID & ~load_use_hazard;   // 跳转发生时清除已取的下一条指令

    // 前递选择：00 = 寄存器堆, 01 = EXE 级 ALU 结果,
    //           10 = MEM 级 ALU 结果, 11 = MEM 级 load 数据
    assign forward_ctrl_A = rs1_EXE_conflict ? 2'b01 :
                            rs1_MEM_conflict ? (MEM_is_load ? 2'b11 : 2'b10) :
                            2'b00;
    assign forward_ctrl_B = rs2_EXE_conflict ? 2'b01 :
                            rs2_MEM_conflict ? (MEM_is_load ? 2'b11 : 2'b10) :
                            2'b00;

    // load-store 前递：EXE 级的 store 要写的数据来自 MEM 级 load 的结果
    assign forward_ctrl_ls = (hazard_optype_EXE == hazard_optype_STORE) &
                             MEM_is_load & (rs2_EXE != 5'd0) & (rs2_EXE == rd_MEM);

    always @(posedge clk) begin
        hazard_optype_EXE <= reg_DE_flush ? 2'd0 : hazard_optype_ID;
        hazard_optype_MEM <= hazard_optype_EXE;
    end

