module    REG_IF_ID(input clk,                                      //IF/ID Latch
                    input rst,
                    input EN,                                       //流水寄存器使能
                    input Data_stall,                               //数据竞争等待
                    input flush,                                    //控制竞争清除并等待
                    input [31:0] PCOUT,                             //指令存储器指针
                    input [31:0] IR,                                //指令存储器输出

                    output reg[31:0] IR_ID,                         //取指锁存
                    output reg[31:0] PCurrent_ID,                   //当前存在指令地址
                    output reg isFlushed
                );

    // 实现：IF/ID 流水寄存器
    // On reset: clear IR_ID to NOP (32'h00000013), PCurrent_ID to 0, isFlushed to 0.
    // When EN is asserted:
    //   - If Data_stall: hold current values (stall the pipeline stage)
    //   - Else if flush: replace IR_ID with NOP (32'h00000013), hold PCurrent_ID, set isFlushed
    //   - Else: latch new instruction IR and program counter PCOUT, clear isFlushed
    always @(posedge clk) begin
        if (rst) begin
            IR_ID       <= 32'h00000013;    // NOP
            PCurrent_ID <= 32'h00000000;
            isFlushed   <= 1'b0;
        end
        else if (EN) begin
            if (Data_stall) begin           // 数据竞争：保持原值
                IR_ID       <= IR_ID;
                PCurrent_ID <= PCurrent_ID;
                isFlushed   <= isFlushed;
            end
            else if (flush) begin           // 控制竞争：插入气泡
                IR_ID       <= 32'h00000013;
                PCurrent_ID <= PCurrent_ID;
                isFlushed   <= 1'b1;
            end
            else begin
                IR_ID       <= IR;
                PCurrent_ID <= PCOUT;
                isFlushed   <= 1'b0;
            end
        end
    end

