`timescale 1ns / 1ps
// 自检测试台：驱动 cmu_sim（cache/cmu/data_ram 独立仿真）
module tb_cmu;
    reg clk = 0;
    reg rst = 1;
    wire [7:0] clk_count, inst_count, hit_count;

    cmu_sim uut(.clk(clk), .rst(rst), .clk_count(clk_count),
                .inst_count(inst_count), .hit_count(hit_count));

    always #10 clk = ~clk;

    integer errors = 0;
    integer i;

    // 期望：inst.v 里 9 条访存，共 128 周期，命中 3 次（data[2],[3],[6]）
    task check_int;
        input [127:0] name;
        input integer got;
        input integer exp;
        begin
            if (got === exp)
                $display("PASS  %0s: expected %0d, got %0d", name, exp, got);
            else begin
                $display("FAIL  %0s: expected %0d, got %0d", name, exp, got);
                errors = errors + 1;
            end
        end
    endtask

    // 记录每条访存指令消耗的周期数
    integer prev_index = 0;
    integer cyc = 0;
    integer start_cyc = 0;
    integer cost [0:8];
    integer ncost = 0;
    integer exp_cost [0:8];

    initial begin
        exp_cost[0] = 18;  // read miss              1+17
        exp_cost[1] = 18;  // write miss             1+17
        exp_cost[2] = 1;   // read hit
        exp_cost[3] = 1;   // write hit
        exp_cost[4] = 18;  // read miss              1+17
        exp_cost[5] = 18;  // write miss             1+17
        exp_cost[6] = 1;   // write hit
        exp_cost[7] = 35;  // read miss + dirty      1+17+17
        exp_cost[8] = 18;  // write miss + clean     1+17
        for (i = 0; i < 9; i = i + 1) cost[i] = -1;
    end

    always @(posedge clk) begin
        if (!rst) begin
            cyc = cyc + 1;
            if (uut.valid && ~uut.stall) begin
                if (ncost < 9) begin
                    cost[ncost] = cyc - start_cyc;
                    ncost = ncost + 1;
                end
                start_cyc = cyc;
            end
        end
    end

    initial begin
        #95 rst = 0;
        start_cyc = 0; cyc = 0;
        #4000;
        $display("=========== CMU / cache unit test ===========");
        for (i = 0; i < 9; i = i + 1) begin
            if (cost[i] === exp_cost[i])
                $display("PASS  access %0d cycles: expected %0d, got %0d", i, exp_cost[i], cost[i]);
            else begin
                $display("FAIL  access %0d cycles: expected %0d, got %0d", i, exp_cost[i], cost[i]);
                errors = errors + 1;
            end
        end
        check_int("total clk_count", clk_count, 128);
        check_int("inst_count", inst_count, 9);
        check_int("hit_count", hit_count, 3);
        if (errors == 0) $display("CMU_TEST_RESULT: PASS");
        else             $display("CMU_TEST_RESULT: FAIL (%0d errors)", errors);
        $finish;
    end
endmodule

