reg[1:0] hazard_optype_EXE, hazard_optype_MEM;
// cache 缺失导致整条流水线冻结时，这两个影子寄存器必须和对应的流水寄存器
// 一起停住（用 reg_EM_EN / reg_DE_EN 门控），否则 rd_EXE / rd_MEM 与
// hazard_optype_EXE / hazard_optype_MEM 会失配，前递判断出错。
always@(posedge clk) begin
    if (reg_EM_EN) hazard_optype_MEM <= hazard_optype_EXE & {2{~reg_EM_flush}};
    if (reg_DE_EN) hazard_optype_EXE <= hazard_optype_ID & {2{~reg_DE_flush}};
end

parameter hazard_optype_ALU = 2'd1;
parameter hazard_optype_LOAD = 2'd2;
parameter hazard_optype_STORE = 2'd3;

// 实现：冒险检测与前递控制
initial begin
    hazard_optype_EXE = 2'd0;
    hazard_optype_MEM = 2'd0;
end

// ID 级真正需要读寄存器（x0 不算）
wire rs1_valid = rs1use_ID & (rs1_ID != 5'd0);
wire rs2_valid = rs2use_ID & (rs2_ID != 5'd0);

// EXE / MEM 级指令是否会写回寄存器
wire EXE_write = (hazard_optype_EXE == hazard_optype_ALU) |
                 (hazard_optype_EXE == hazard_optype_LOAD);
wire MEM_write = (hazard_optype_MEM == hazard_optype_ALU) |
                 (hazard_optype_MEM == hazard_optype_LOAD);

wire EXE_is_load = hazard_optype_EXE == hazard_optype_LOAD;
wire MEM_is_load = hazard_optype_MEM == hazard_optype_LOAD;

// 相关判断
wire rs1_forward_EXE = rs1_valid & EXE_write & (rs1_ID == rd_EXE);
wire rs2_forward_EXE = rs2_valid & EXE_write & (rs2_ID == rd_EXE);
wire rs1_forward_MEM = rs1_valid & MEM_write & (rs1_ID == rd_MEM);
wire rs2_forward_MEM = rs2_valid & MEM_write & (rs2_ID == rd_MEM);

// load-use 冒险：EXE 级是 load，ID 级需要它的结果 -> 必须暂停一拍。
// 例外：ID 级是 store 且只有 rs2（待写入的数据）相关时，可以留到 EXE/MEM
//       级用 load-store 前递解决，不需要暂停。
wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;
wire load_stall = EXE_is_load &
                  (rs1_forward_EXE | (rs2_forward_EXE & ~ID_is_store));

// cmu_stall 时整条流水线冻结（PC 与所有流水寄存器都不使能），
// 访存操作不会被重复发起。
assign PC_EN_IF = ~cmu_stall & ~load_stall;
assign reg_FD_stall = load_stall;
assign reg_FD_flush = Branch_ID & ~load_stall;   // 跳转发生时清除已取的下一条指令
assign reg_DE_flush = load_stall;                // 向 EXE 级插入气泡

// 前递选择：00 = 寄存器堆, 01 = EXE 级 ALU 结果,
//           10 = MEM 级 ALU 结果, 11 = MEM 级 load 数据
assign forward_ctrl_A = rs1_forward_EXE ? 2'b01 :
                        rs1_forward_MEM ? (MEM_is_load ? 2'b11 : 2'b10) :
                        2'b00;
assign forward_ctrl_B = rs2_forward_EXE ? 2'b01 :
                        rs2_forward_MEM ? (MEM_is_load ? 2'b11 : 2'b10) :
                        2'b00;

// load-store 前递：EXE 级 store 要写的数据来自 MEM 级 load 的结果
assign forward_ctrl_ls = (hazard_optype_EXE == hazard_optype_STORE) &
                         MEM_is_load & (rs2_EXE != 5'd0) & (rs2_EXE == rd_MEM);

