`timescale 1ns / 1ps
//
// lab4 自检测试台：运行 src/lab4/mem_test.s 汇编出的 core/rom.mem，
// 检查 load 结果、cache 命中/缺失序列、脏行写回、以及最终循环状态。
//
module tb_core;

    reg clk = 0;
    reg rst = 1;
    wire [31:0] debug_data, wb_pc, wb_inst, mem_addr, mem_data;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(debug_data),
        .wb_pc(wb_pc),
        .wb_inst(wb_inst),
        .mem_addr(mem_addr),
        .mem_data(mem_data),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    always #10 clk = ~clk;

    localparam S_IDLE = 0, S_PRE_BACK = 1, S_BACK = 2, S_FILL = 3, S_WAIT = 4;

    integer errors = 0;
    integer i;

    // ---------------- 访存事件记录 ----------------
    integer n_acc = 0;
    reg [31:0] acc_addr  [0:31];
    reg        acc_miss  [0:31];
    reg        acc_wb    [0:31];
    reg        acc_write [0:31];
    integer    acc_cyc   [0:31];

    reg cur_miss = 0;
    reg cur_wb   = 0;
    integer cur_cyc = 0;

    // ---------------- 写回寄存器事件记录 ----------------
    integer n_wb = 0;
    reg [4:0]  wb_rd   [0:63];
    reg [31:0] wb_val  [0:63];

    integer cyc = 0;
    reg done = 0;

    // 在 posedge 前 1ns 采样：此时本周期的 state / cache_hit / stall 都已稳定
    always @(negedge clk) begin
        #9;
        if (!rst && !done) begin
            cyc = cyc + 1;

            // ---- 访存事件 ----
            if (core.DatatoReg_MEM | core.mem_w_MEM) begin
                cur_cyc = cur_cyc + 1;
                if (core.cmu_state != S_IDLE) cur_miss = 1;
                if (core.cmu_state == S_BACK || core.cmu_state == S_PRE_BACK) cur_wb = 1;
                if (!core.cmu_stall) begin
                    if (n_acc < 32) begin
                        acc_addr[n_acc]  = core.ALUout_MEM;
                        acc_miss[n_acc]  = cur_miss;
                        acc_wb[n_acc]    = cur_wb;
                        acc_write[n_acc] = core.mem_w_MEM;
                        acc_cyc[n_acc]   = cur_cyc;
                        n_acc = n_acc + 1;
                    end
                    cur_miss = 0; cur_wb = 0; cur_cyc = 0;
                end
            end

            // ---- 寄存器写回事件 ----
            if (core.RegWrite_WB && core.rd_WB != 5'd0 && core.reg_MW_EN) begin
                if (n_wb < 64) begin
                    wb_rd[n_wb]  = core.rd_WB;
                    wb_val[n_wb] = core.wt_data_WB;
                    n_wb = n_wb + 1;
                end
            end
        end
    end

    // ---------------- 期望值 ----------------
    reg [31:0] exp_acc_addr  [0:11];
    reg        exp_acc_miss  [0:11];
    reg        exp_acc_wb    [0:11];
    reg [8*24:1] exp_acc_name [0:11];

    reg [4:0]  exp_wb_rd  [0:10];
    reg [31:0] exp_wb_val [0:10];

    task chk32;
        input [8*40:1] name;
        input [31:0] got;
        input [31:0] exp;
        begin
            if (got === exp)
                $display("PASS  %0s: expected 0x%08x, got 0x%08x", name, exp, got);
            else begin
                $display("FAIL  %0s: expected 0x%08x, got 0x%08x", name, exp, got);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // mem_test.s 中注释描述的访存序列
        exp_acc_addr[0]=32'h01C; exp_acc_miss[0]=1; exp_acc_wb[0]=0; exp_acc_name[0]="lb  x1,0x1C   miss";
        exp_acc_addr[1]=32'h01C; exp_acc_miss[1]=0; exp_acc_wb[1]=0; exp_acc_name[1]="lh  x2,0x1C   hit";
        exp_acc_addr[2]=32'h01C; exp_acc_miss[2]=0; exp_acc_wb[2]=0; exp_acc_name[2]="lw  x3,0x1C   hit";
        exp_acc_addr[3]=32'h01C; exp_acc_miss[3]=0; exp_acc_wb[3]=0; exp_acc_name[3]="lbu x4,0x1C   hit";
        exp_acc_addr[4]=32'h01C; exp_acc_miss[4]=0; exp_acc_wb[4]=0; exp_acc_name[4]="lhu x5,0x1C   hit";
        exp_acc_addr[5]=32'h210; exp_acc_miss[5]=1; exp_acc_wb[5]=0; exp_acc_name[5]="lw  x0,0x210  miss";
        exp_acc_addr[6]=32'h000; exp_acc_miss[6]=1; exp_acc_wb[6]=0; exp_acc_name[6]="sb  x1,0x0    miss";
        exp_acc_addr[7]=32'h004; exp_acc_miss[7]=0; exp_acc_wb[7]=0; exp_acc_name[7]="sh  x1,0x4    hit";
        exp_acc_addr[8]=32'h008; exp_acc_miss[8]=0; exp_acc_wb[8]=0; exp_acc_name[8]="sw  x1,0x8    hit";
        exp_acc_addr[9]=32'h200; exp_acc_miss[9]=1; exp_acc_wb[9]=0; exp_acc_name[9]="lw  x6,0x200  miss";
        exp_acc_addr[10]=32'h400;exp_acc_miss[10]=1;exp_acc_wb[10]=1;exp_acc_name[10]="lw  x7,0x400  miss+wb";
        exp_acc_addr[11]=32'h410;exp_acc_miss[11]=1;exp_acc_wb[11]=0;exp_acc_name[11]="lw  x8,0x410  miss";

        exp_wb_rd[0]=5'd1;  exp_wb_val[0]=32'hFFFFFFF0;  // lb
        exp_wb_rd[1]=5'd2;  exp_wb_val[1]=32'hFFFFF0F0;  // lh
        exp_wb_rd[2]=5'd3;  exp_wb_val[2]=32'hF0F0F0F0;  // lw
        exp_wb_rd[3]=5'd4;  exp_wb_val[3]=32'h000000F0;  // lbu
        exp_wb_rd[4]=5'd5;  exp_wb_val[4]=32'h0000F0F0;  // lhu
        exp_wb_rd[5]=5'd1;  exp_wb_val[5]=32'hABCDE000;  // lui
        exp_wb_rd[6]=5'd1;  exp_wb_val[6]=32'hABCDE71C;  // addi
        exp_wb_rd[7]=5'd6;  exp_wb_val[7]=32'h00000000;  // lw 0x200
        exp_wb_rd[8]=5'd7;  exp_wb_val[8]=32'h00000000;  // lw 0x400
        exp_wb_rd[9]=5'd8;  exp_wb_val[9]=32'h00000000;  // lw 0x410
        exp_wb_rd[10]=5'd16;exp_wb_val[10]=32'h000000ED; // ori
    end

    integer nchk;
    initial begin
        #45 rst = 0;
        #20000;
        done = 1;
        $display("=========== lab4 core test ===========");

        // 1) cache 命中/缺失序列
        $display("--- memory access trace (expected vs actual) ---");
        if (n_acc < 12) begin
            $display("FAIL  only %0d memory accesses observed, expected >= 12", n_acc);
            errors = errors + 1;
        end
        nchk = (n_acc < 12) ? n_acc : 12;
        for (i = 0; i < nchk; i = i + 1) begin
            if (acc_addr[i] === exp_acc_addr[i] && acc_miss[i] === exp_acc_miss[i]
                && acc_wb[i] === exp_acc_wb[i])
                $display("PASS  %0s | addr=0x%03x %s%s (%0d cycles)", exp_acc_name[i],
                         acc_addr[i], acc_miss[i] ? "MISS" : "HIT ",
                         acc_wb[i] ? "+writeback" : "", acc_cyc[i]);
            else begin
                $display("FAIL  %0s | got addr=0x%03x miss=%0d wb=%0d (expected addr=0x%03x miss=%0d wb=%0d)",
                         exp_acc_name[i], acc_addr[i], acc_miss[i], acc_wb[i],
                         exp_acc_addr[i], exp_acc_miss[i], exp_acc_wb[i]);
                errors = errors + 1;
            end
        end
        if (n_acc !== 12) begin
            $display("FAIL  number of memory accesses: expected 12, got %0d", n_acc);
            errors = errors + 1;
        end
        else $display("PASS  number of memory accesses: expected 12, got 12");

        // 2) 寄存器写回序列
        $display("--- register writeback sequence ---");
        if (n_wb < 11) begin
            $display("FAIL  only %0d register writebacks observed, expected >= 11", n_wb);
            errors = errors + 1;
        end
        nchk = (n_wb < 11) ? n_wb : 11;
        for (i = 0; i < nchk; i = i + 1) begin
            if (wb_rd[i] === exp_wb_rd[i] && wb_val[i] === exp_wb_val[i])
                $display("PASS  wb[%0d] x%0d = 0x%08x", i, wb_rd[i], wb_val[i]);
            else begin
                $display("FAIL  wb[%0d]: expected x%0d = 0x%08x, got x%0d = 0x%08x",
                         i, exp_wb_rd[i], exp_wb_val[i], wb_rd[i], wb_val[i]);
                errors = errors + 1;
            end
        end

        // 3) 最终寄存器堆内容
        $display("--- final register file ---");
        chk32("x1  (lui+addi)",     core.register.register[1],  32'hABCDE71C);
        chk32("x2  (lh  0x1C)",     core.register.register[2],  32'hFFFFF0F0);
        chk32("x3  (lw  0x1C)",     core.register.register[3],  32'hF0F0F0F0);
        chk32("x4  (lbu 0x1C)",     core.register.register[4],  32'h000000F0);
        chk32("x5  (lhu 0x1C)",     core.register.register[5],  32'h0000F0F0);
        chk32("x6  (lw  0x200)",    core.register.register[6],  32'h00000000);
        chk32("x7  (lw  0x400)",    core.register.register[7],  32'h00000000);
        chk32("x8  (lw  0x410)",    core.register.register[8],  32'h00000000);
        chk32("x16 (ori 0xED)",     core.register.register[16], 32'h000000ED);

        // 4) 脏行写回是否真的到达 data_ram
        $display("--- dirty line written back to data_ram (0x000..0x00C) ---");
        chk32("ram[0x000] after sb", core.RAM.data[0], 32'h0000801C);
        chk32("ram[0x004] after sh", core.RAM.data[1], 32'h0000071C);
        chk32("ram[0x008] after sw", core.RAM.data[2], 32'hABCDE71C);
        chk32("ram[0x00C] untouched",core.RAM.data[3], 32'h00000014);

        // 5) 程序停在最后的死循环里
        $display("--- final state ---");
        if ((core.PC_WB === 32'h3C || core.PC_WB === 32'h40) &&
            core.register.register[16] === 32'h000000ED)
            $display("PASS  reached final loop: PC_WB=0x%08x inst_WB=0x%08x x16=0x%08x",
                     core.PC_WB, core.inst_WB, core.register.register[16]);
        else begin
            $display("FAIL  final loop: PC_WB=0x%08x inst_WB=0x%08x x16=0x%08x (expected PC 0x3C/0x40, x16=0xED)",
                     core.PC_WB, core.inst_WB, core.register.register[16]);
            errors = errors + 1;
        end

        if (errors == 0) $display("CORE_TEST_RESULT: PASS");
        else             $display("CORE_TEST_RESULT: FAIL (%0d errors)", errors);
        $finish;
    end

endmodule

`timescale 1ns / 1ps
// 压力测试：覆盖全部 ALU 运算、立即数格式、前递路径、load-use 暂停、
// load-store 前递、6 种条件分支、JAL / JALR。
module tb_stress;
    reg clk = 0, rst = 1;
    wire [31:0] debug_data, wb_pc, wb_inst, mem_addr, mem_data;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0), .debug_data(debug_data),
        .wb_pc(wb_pc), .wb_inst(wb_inst), .mem_addr(mem_addr), .mem_data(mem_data),
        .clk(clk), .rst(rst), .interrupter(1'b0));

    always #10 clk = ~clk;

    integer errors = 0;
    task chk;
        input [8*32:1] name;
        input [31:0] got, exp;
        begin
            if (got === exp) $display("PASS  %0s = 0x%08x", name, got);
            else begin
                $display("FAIL  %0s: expected 0x%08x, got 0x%08x", name, exp, got);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        #45 rst = 0;
        #40000;
        $display("=========== lab4 pipeline stress test ===========");
        chk("x1  addi",   core.register.register[1],  32'h00000005);
        chk("x2  addi neg", core.register.register[2], 32'hFFFFFFFD);
        chk("x3  add",    core.register.register[3],  32'h00000002);
        chk("x4  sub",    core.register.register[4],  32'h00000008);
        chk("x5  and",    core.register.register[5],  32'h00000005);
        chk("x6  or",     core.register.register[6],  32'hFFFFFFFD);
        chk("x7  xor",    core.register.register[7],  32'hFFFFFFF8);
        chk("x8  sll",    core.register.register[8],  32'h00000014);
        chk("x9  srl",    core.register.register[9],  32'h3FFFFFFF);
        chk("x10 sra",    core.register.register[10], 32'hFFFFFFFF);
        chk("x11 slt",    core.register.register[11], 32'h00000001);
        chk("x12 sltu",   core.register.register[12], 32'h00000000);
        chk("x13 slti",   core.register.register[13], 32'h00000001);
        chk("x14 srai",   core.register.register[14], 32'hFFFFFFFE);
        chk("x15 lui",    core.register.register[15], 32'h12345000);
        chk("x16 auipc",  core.register.register[16], 32'h0000103C);
        chk("x17 lw",     core.register.register[17], 32'h12345000);
        chk("x18 load-use addi", core.register.register[18], 32'h12345001);
        chk("x19 lw",     core.register.register[19], 32'h12345000);
        chk("x20 ls-fwd lw",     core.register.register[20], 32'h12345000);
        chk("x21 sb/lbu", core.register.register[21], 32'h00000005);
        chk("x22 sh/lh",  core.register.register[22], 32'hFFFFFFFD);
        chk("x23 sh/lhu", core.register.register[23], 32'h0000FFFD);
        chk("x24 beq taken",     core.register.register[24], 32'h00000001);
        chk("x25 bne/blt",       core.register.register[25], 32'h00000007);
        chk("x26 bltu/bge",      core.register.register[26], 32'h00000009);
        chk("x27 bgeu not taken",core.register.register[27], 32'h0000000B);
        chk("x28 jal link",      core.register.register[28], 32'h000000A4);
        chk("x29 jalr base",     core.register.register[29], 32'h000000B4);
        chk("x30 jalr link",     core.register.register[30], 32'h000000B0);
        chk("x31 ori",           core.register.register[31], 32'h000000ED);
        // 存储器内容
        chk("ram[0x100]", core.RAM.data[64], 32'h12345000);
        chk("ram[0x104]", core.RAM.data[65], 32'h12345000);
        // 最终停在死循环
        if (core.PC_WB === 32'hB8 || core.PC_WB === 32'hBC)
            $display("PASS  final loop PC_WB=0x%08x", core.PC_WB);
        else begin
            $display("FAIL  final loop: PC_WB=0x%08x (expected 0xB8/0xBC)", core.PC_WB);
            errors = errors + 1;
        end
        // X 检查
        if (^{core.PC_IF, core.inst_WB, core.wt_data_WB, core.ALUout_MEM} === 1'bx) begin
            $display("FAIL  X propagation detected on core signals");
            errors = errors + 1;
        end else $display("PASS  no X on PC_IF / inst_WB / wt_data_WB / ALUout_MEM");

        if (errors == 0) $display("STRESS_TEST_RESULT: PASS");
        else             $display("STRESS_TEST_RESULT: FAIL (%0d errors)", errors);
        $finish;
    end
endmodule

